// Replay the unchanged supplement checker on the exact before/after files from the trial.
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { claimRow, lineList, rejectedClaims, supplementChecks } from "../building-loop/governance/preflight.mjs";

const run = resolve(process.argv[2]);
const root = resolve(run, "reuse/workspace");
const json = file => JSON.parse(readFileSync(file, "utf8"));
const digest = data => createHash("sha256").update(data).digest("hex");
const receipt = json(resolve(root, "records/audit-final.json"));
const events = readFileSync(resolve(run, "events.jsonl"), "utf8").trim().split(/\r?\n/).map(line => JSON.parse(line));
const oldCandidate = events.filter(e => e.type === "tool/call" && e.data.name === "building_loop_file")
  .map(e => JSON.parse(e.data.arguments))
  .find(a => a.action === "write" && a.path === "module/candidate.md" && digest(a.content) === receipt.candidateSha256);
if (!oldCandidate) throw new Error("Unable to recover exact rejected candidate from write events");

const beforeBytes = Buffer.from(oldCandidate.content);
const afterBytes = readFileSync(resolve(root, "module/candidate.md"));
const beforeLines = lineList(beforeBytes);
const afterLines = lineList(afterBytes);
const spec = json(resolve(root, "BUILDING-LOOP.json")).units.K01;
spec.calculations ??= {};
const readable = spec.phases.supplement.read;
const rejected = receipt.checks.filter(row => row.id === "C3" && row.status === "unsupported");
const before = rejectedClaims(root, spec, beforeLines, rejected, readable);
const after = rejectedClaims(root, spec, afterLines, rejected, readable);
const result = supplementChecks(root, spec, afterLines, readable, {
  unsupported: ["C3"], rejected: before, seen: json(resolve(run, "reuse/ledger-state.json")).unit.seen,
});
const finding = {
  spec: "building-loop-preflight-replay/1",
  input: { rejectedSha256: digest(beforeBytes), revisedSha256: digest(afterBytes) },
  claim: "C3", changedText: claimRow(beforeLines, "C3").body !== claimRow(afterLines, "C3").body,
  rejectedContainsUnregisteredPrecision: beforeBytes.includes("27.3"), revisedContainsUnregisteredPrecision: afterBytes.includes("27.3"),
  beforeFingerprint: before.C3, afterFingerprint: after.C3, preflight: result,
  interpretation: "The current conclusion() cuts the claim at the first citation label, hiding changes after that label; unchanged source coordinates do not distinguish a removed unsupported qualifier.",
};
if (!finding.changedText || !finding.rejectedContainsUnregisteredPrecision || finding.revisedContainsUnregisteredPrecision
  || before.C3.conclusion !== after.C3.conclusion || result.ok) throw new Error("Expected replay behavior was not reproduced");
writeFileSync(resolve(run, "reuse/preflight-replay.json"), JSON.stringify(finding, null, 2) + "\n", "utf8");
console.log("Replayed real C3: removed unregistered precision, conclusion hash unchanged, preflight blocked");

