          const agent = ctx.agents.get(created.sessionId ?? created.id);
          if (!agent) throw new Error("Session controller returned no live agent");
          const lookup = { cwd, scope: agent };
          const visible = await ctx.skills.list(lookup);
          visibleSkillCount = visible.length;
          boundPreset = ctx.agentPresets.presetForSession(agent.session) ?? null;
          for (const skillName of ["dispatch-protocol", "project-index"]) {
            const skill = await ctx.skills.get(skillName, lookup);
            skillDiagnostics.push({
              name: skillName,
              listed: visible.some(item => item.name === skillName),
              content: Boolean(skill?.content),
              provider: skill?.provider ?? null,
              resourceBase: skill?.resourceBase ?? null,
            });
            if (skill?.content && skill.resourceBase?.kind === "directory") {
              const packageName = process.env.BUILDING_LOOP_SMOKE_PACKAGE;
              const resource = skill.resourceBase.path.replaceAll("\\", "/");
              if (resource.includes("/node_modules/" + packageName + "/skills/")) {
                scopedSkills.push(skillName);
              }
            }
          }
        } catch (error) {
          sessionError = String(error);
        }
      }
      console.log("BUILDING_LOOP_SMOKE " + JSON.stringify({
        id: preset.id,
        name: preset.name,
        broken: preset.broken ?? null,
        skillProvider: modules.includes("dsh-skill-filesystem"),
        resume: modules.includes(process.env.BUILDING_LOOP_SMOKE_PACKAGE + "/turn-resume"),
        leakedServices: active?.leakedServices ?? null,
        scopedSkills,
        skillDiagnostics,
        visibleSkillCount,
        boundPreset,
        sessionError,
      }));
      clearInterval(timer);
    } finally {
      checking = false;
    }
  }, 250);
  ctx.on("dispose", () => clearInterval(timer));
}
